  1245    /*************************************************************************/
  1246    /*                                                                       */
  1247    /* <Function>                                                            */
  1248    /*    TT_Get_MM_Var                                                      */
  1249    /*                                                                       */
  1250    /* <Description>                                                         */
  1251    /*    Check that the font's `fvar' table is valid, parse it, and return  */
  1252    /*    those data.                                                        */
  1253    /*                                                                       */
  1254    /* <InOut>                                                               */
  1255    /*    face   :: The font face.                                           */
  1256    /*              TT_Get_MM_Var initializes the blend structure.           */
  1257    /*                                                                       */
  1258    /* <Output>                                                              */
  1259    /*    master :: The `fvar' data (must be freed by caller).  Can be NULL, */
  1260    /*              which makes this function simply load MM support.        */
  1261    /*                                                                       */
  1262    /* <Return>                                                              */
  1263    /*    FreeType error code.  0 means success.                             */
  1264    /*                                                                       */
  1265    FT_LOCAL_DEF( FT_Error )
  1266    TT_Get_MM_Var( TT_Face      face,
  1267                   FT_MM_Var*  *master )
  1268    {
  1269      FT_Stream            stream = face->root.stream;
  1270      FT_Memory            memory = face->root.memory;
  1271      FT_ULong             table_len;
  1272      FT_Error             error  = FT_Err_Ok;
  1273      FT_ULong             fvar_start;
  1274      FT_Int               i, j;
  1275      FT_MM_Var*           mmvar = NULL;
  1276      FT_Fixed*            next_coords;
  1277      FT_String*           next_name;
  1278      FT_Var_Axis*         a;
  1279      FT_Var_Named_Style*  ns;
  1280      GX_FVar_Head         fvar_head;
  1281      FT_Bool              usePsName;
  1282
  1283      static const FT_Frame_Field  fvar_fields[] =
  1284      {
  1285
  1286  #undef  FT_STRUCTURE
  1287  #define FT_STRUCTURE  GX_FVar_Head
  1288
  1289        FT_FRAME_START( 16 ),
  1290          FT_FRAME_LONG  ( version ),
  1291          FT_FRAME_USHORT( offsetToData ),
  1292          FT_FRAME_USHORT( countSizePairs ),
  1293          FT_FRAME_USHORT( axisCount ),
  1294          FT_FRAME_USHORT( axisSize ),
  1295          FT_FRAME_USHORT( instanceCount ),
  1296          FT_FRAME_USHORT( instanceSize ),
  1297        FT_FRAME_END
  1298      };
  1299
  1300      static const FT_Frame_Field  fvaraxis_fields[] =
  1301      {
  1302
  1303  #undef  FT_STRUCTURE
  1304  #define FT_STRUCTURE  GX_FVar_Axis
  1305
  1306        FT_FRAME_START( 20 ),
  1307          FT_FRAME_ULONG ( axisTag ),
  1308          FT_FRAME_LONG  ( minValue ),
  1309          FT_FRAME_LONG  ( defaultValue ),
  1310          FT_FRAME_LONG  ( maxValue ),
  1311          FT_FRAME_USHORT( flags ),
  1312          FT_FRAME_USHORT( nameID ),
  1313        FT_FRAME_END
  1314      };
  1315
  1316
  1317      /* read the font data and set up the internal representation */
  1318      /* if not already done                                       */
  1319
  1320      if ( face->blend == NULL )
  1321      {
  1322        FT_TRACE2(( "FVAR " ));
  1323
  1324        /* both `fvar' and `gvar' must be present */
  1325        if ( ( error = face->goto_table( face, TTAG_gvar,
  1326                                         stream, &table_len ) ) != 0 )
  1327        {
  1328          FT_TRACE1(( "\n"
  1329                      "TT_Get_MM_Var: `gvar' table is missing\n" ));
  1330          goto Exit;
  1331        }
  1332
  1333        if ( ( error = face->goto_table( face, TTAG_fvar,
  1334                                         stream, &table_len ) ) != 0 )
  1335        {
  1336          FT_TRACE1(( "is missing\n" ));
  1337          goto Exit;
  1338        }
  1339
  1340        fvar_start = FT_STREAM_POS( );
  1341
  1342        if ( FT_STREAM_READ_FIELDS( fvar_fields, &fvar_head ) )
  1343          goto Exit;
  1344
  1345        if ( fvar_head.version != (FT_Long)0x00010000L                      ||
  1346  #if 0
  1347             /* fonts like `JamRegular.ttf' have an incorrect value for */
  1348             /* `countSizePairs'; since value 2 is hard-coded in `fvar' */
  1349             /* version 1.0, we simply ignore it                        */
  1350             fvar_head.countSizePairs != 2                                  ||
  1351  #endif
  1352             fvar_head.axisSize != 20                                       ||
  1353             /* axisCount limit implied by 16-bit instanceSize */
  1354             fvar_head.axisCount > 0x3FFE                                   ||
  1355             fvar_head.instanceCount > 0x7EFF                               ||
  1356             fvar_head.offsetToData + fvar_head.axisCount * 20U +
  1357               fvar_head.instanceCount * fvar_head.instanceSize > table_len )
  1358        {
  1359          FT_TRACE1(( "\n"
  1360                      "TT_Get_MM_Var: invalid `fvar' header\n" ));
  1361          error = FT_THROW( Invalid_Table );
  1362          goto Exit;
  1363        }
  1364
  1365        if ( fvar_head.instanceSize == 4 + 4 * fvar_head.axisCount )
  1366          usePsName = FALSE;
  1367        else if ( fvar_head.instanceSize == 6 + 4 * fvar_head.axisCount )
  1368          usePsName = TRUE;
  1369        else
  1370        {
  1371          FT_TRACE1(( "\n"
  1372                      "TT_Get_MM_Var: invalid `fvar' header\n" ));
  1373          error = FT_THROW( Invalid_Table );
  1374          goto Exit;
  1375        }
  1376
  1377        FT_TRACE2(( "loaded\n" ));
  1378
  1379        FT_TRACE5(( "number of GX style axes: %d\n", fvar_head.axisCount ));
  1380
  1381        if ( FT_NEW( face->blend ) )
  1382          goto Exit;
  1383
  1384        /* cannot overflow 32-bit arithmetic because of limits above */
  1385        face->blend->mmvar_len =
  1386          sizeof ( FT_MM_Var ) +
  1387          fvar_head.axisCount * sizeof ( FT_Var_Axis ) +
  1388          fvar_head.instanceCount * sizeof ( FT_Var_Named_Style ) +
  1389          fvar_head.instanceCount * fvar_head.axisCount * sizeof ( FT_Fixed ) +
  1390          5 * fvar_head.axisCount;
  1391
  1392        if ( FT_ALLOC( mmvar, face->blend->mmvar_len ) )
  1393          goto Exit;
  1394        face->blend->mmvar = mmvar;
  1395
  1396        /* set up pointers and offsets into the `mmvar' array; */
  1397        /* the data gets filled in later on                    */
  1398
  1399        mmvar->num_axis =
  1400          fvar_head.axisCount;
  1401        mmvar->num_designs =
  1402          ~0U;                   /* meaningless in this context; each glyph */
  1403                                 /* may have a different number of designs  */
  1404                                 /* (or tuples, as called by Apple)         */
  1405        mmvar->num_namedstyles =
  1406          fvar_head.instanceCount;
  1407        mmvar->axis =
  1408          (FT_Var_Axis*)&( mmvar[1] );
  1409        mmvar->namedstyle =
  1410          (FT_Var_Named_Style*)&( mmvar->axis[fvar_head.axisCount] );
  1411
  1412        next_coords =
  1413          (FT_Fixed*)&( mmvar->namedstyle[fvar_head.instanceCount] );
  1414        for ( i = 0; i < fvar_head.instanceCount; i++ )
  1415        {
  1416          mmvar->namedstyle[i].coords  = next_coords;
  1417          next_coords                 += fvar_head.axisCount;
  1418        }
  1419
  1420        next_name = (FT_String*)next_coords;
  1421        for ( i = 0; i < fvar_head.axisCount; i++ )
  1422        {
  1423          mmvar->axis[i].name  = next_name;
  1424          next_name           += 5;
  1425        }
  1426
  1427        /* now fill in the data */
  1428
  1429        if ( FT_STREAM_SEEK( fvar_start + fvar_head.offsetToData ) )
  1430          goto Exit;
  1431
  1432        a = mmvar->axis;
  1433        for ( i = 0; i < fvar_head.axisCount; i++ )
  1434        {
  1435          GX_FVar_Axis  axis_rec;
  1436
  1437
  1438          if ( FT_STREAM_READ_FIELDS( fvaraxis_fields, &axis_rec ) )
  1439            goto Exit;
  1440          a->tag     = axis_rec.axisTag;
  1441          a->minimum = axis_rec.minValue;
  1442          a->def     = axis_rec.defaultValue;
  1443          a->maximum = axis_rec.maxValue;
  1444          a->strid   = axis_rec.nameID;
  1445
  1446          a->name[0] = (FT_String)(   a->tag >> 24 );
  1447          a->name[1] = (FT_String)( ( a->tag >> 16 ) & 0xFF );
  1448          a->name[2] = (FT_String)( ( a->tag >>  8 ) & 0xFF );
  1449          a->name[3] = (FT_String)( ( a->tag       ) & 0xFF );
  1450          a->name[4] = '\0';
  1451
  1452          FT_TRACE5(( "  \"%s\": minimum=%.4f, default=%.4f, maximum=%.4f\n",
  1453                      a->name,
  1454                      a->minimum / 65536.0,
  1455                      a->def / 65536.0,
  1456                      a->maximum / 65536.0 ));
  1457
  1458          a++;
  1459        }
  1460
  1461        FT_TRACE5(( "\n" ));
  1462
  1463        ns = mmvar->namedstyle;
  1464        for ( i = 0; i < fvar_head.instanceCount; i++, ns++ )
  1465        {
  1466          /* PostScript names add 2 bytes to the instance record size */
  1467          if ( FT_FRAME_ENTER( ( usePsName ? 6L : 4L ) +
  1468                               4L * fvar_head.axisCount ) )
  1469            goto Exit;
  1470
  1471          ns->strid       =    FT_GET_USHORT();
  1472          (void) /* flags = */ FT_GET_USHORT();
  1473
  1474          for ( j = 0; j < fvar_head.axisCount; j++ )
  1475            ns->coords[j] = FT_GET_LONG();
  1476
  1477          if ( usePsName )
  1478            ns->psid = FT_GET_USHORT();
  1479
  1480          FT_FRAME_EXIT();
  1481        }
  1482      }
  1483
  1484      /* fill the output array if requested */
  1485
  1486      if ( master != NULL )
  1487      {
  1488        FT_UInt  n;
  1489
  1490
  1491        if ( FT_ALLOC( mmvar, face->blend->mmvar_len ) )
  1492          goto Exit;
  1493        FT_MEM_COPY( mmvar, face->blend->mmvar, face->blend->mmvar_len );
  1494
  1495        mmvar->axis =
  1496          (FT_Var_Axis*)&( mmvar[1] );
  1497        mmvar->namedstyle =
  1498          (FT_Var_Named_Style*)&( mmvar->axis[mmvar->num_axis] );
  1499        next_coords =
  1500          (FT_Fixed*)&( mmvar->namedstyle[mmvar->num_namedstyles] );
  1501
  1502        for ( n = 0; n < mmvar->num_namedstyles; n++ )
  1503        {
  1504          mmvar->namedstyle[n].coords  = next_coords;
  1505          next_coords                 += mmvar->num_axis;
  1506        }
  1507
  1508        a         = mmvar->axis;
  1509        next_name = (FT_String*)next_coords;
  1510        for ( n = 0; n < mmvar->num_axis; n++ )
  1511        {
  1512          a->name = next_name;
  1513
  1514          /* standard PostScript names for some standard apple tags */
  1515          if ( a->tag == TTAG_wght )
  1516            a->name = (char*)"Weight";
  1517          else if ( a->tag == TTAG_wdth )
  1518            a->name = (char*)"Width";
  1519          else if ( a->tag == TTAG_opsz )
  1520            a->name = (char*)"OpticalSize";
  1521          else if ( a->tag == TTAG_slnt )
  1522            a->name = (char*)"Slant";
  1523
  1524          next_name += 5;
  1525          a++;
  1526        }
  1527
  1528        *master = mmvar;
  1529      }
  1530
  1531    Exit:
  1532      return error;
  1533    }
