  1536    /*************************************************************************/
  1537    /*                                                                       */
  1538    /* <Function>                                                            */
  1539    /*    TT_Set_MM_Blend                                                    */
  1540    /*                                                                       */
  1541    /* <Description>                                                         */
  1542    /*    Set the blend (normalized) coordinates for this instance of the    */
  1543    /*    font.  Check that the `gvar' table is reasonable and does some     */
  1544    /*    initial preparation.                                               */
  1545    /*                                                                       */
  1546    /* <InOut>                                                               */
  1547    /*    face       :: The font.                                            */
  1548    /*                  Initialize the blend structure with `gvar' data.     */
  1549    /*                                                                       */
  1550    /* <Input>                                                               */
  1551    /*    num_coords :: The number of available coordinates.  If it is       */
  1552    /*                  larger than the number of axes, ignore the excess    */
  1553    /*                  values.  If it is smaller than the number of axes,   */
  1554    /*                  use the default value (0) for the remaining axes.    */
  1555    /*                                                                       */
  1556    /*    coords     :: An array of `num_coords', each between [-1,1].       */
  1557    /*                                                                       */
  1558    /* <Return>                                                              */
  1559    /*    FreeType error code.  0 means success.                             */
  1560    /*                                                                       */
  1561    FT_LOCAL_DEF( FT_Error )
  1562    TT_Set_MM_Blend( TT_Face    face,
  1563                     FT_UInt    num_coords,
  1564                     FT_Fixed*  coords )
  1565    {
  1566      FT_Error    error = FT_Err_Ok;
  1567      GX_Blend    blend;
  1568      FT_MM_Var*  mmvar;
  1569      FT_UInt     i;
  1570      FT_Bool     is_default_instance = 1;
  1571      FT_Memory   memory = face->root.memory;
  1572
  1573      enum
  1574      {
  1575        mcvt_retain,
  1576        mcvt_modify,
  1577        mcvt_load
  1578
  1579      } manageCvt;
  1580
  1581
  1582      face->doblend = FALSE;
  1583
  1584      if ( face->blend == NULL )
  1585      {
  1586        if ( ( error = TT_Get_MM_Var( face, NULL ) ) != 0 )
  1587          goto Exit;
  1588      }
  1589
  1590      blend = face->blend;
  1591      mmvar = blend->mmvar;
  1592
  1593      if ( num_coords > mmvar->num_axis )
  1594      {
  1595        FT_TRACE2(( "TT_Set_MM_Blend: only using first %d of %d coordinates\n",
  1596                    mmvar->num_axis, num_coords ));
  1597        num_coords = mmvar->num_axis;
  1598      }
  1599
  1600      FT_TRACE5(( "normalized design coordinates:\n" ));
  1601
  1602      for ( i = 0; i < num_coords; i++ )
  1603      {
  1604        FT_TRACE5(( "  %.4f\n", coords[i] / 65536.0 ));
  1605        if ( coords[i] < -0x00010000L || coords[i] > 0x00010000L )
  1606        {
  1607          FT_TRACE1(( "TT_Set_MM_Blend: normalized design coordinate %.4f\n"
  1608                      "                 is out of range [-1;1]\n",
  1609                      coords[i] / 65536.0 ));
  1610          error = FT_THROW( Invalid_Argument );
  1611          goto Exit;
  1612        }
  1613
  1614        if ( coords[i] != 0 )
  1615          is_default_instance = 0;
  1616      }
  1617
  1618      FT_TRACE5(( "\n" ));
  1619
  1620      if ( blend->glyphoffsets == NULL )
  1621        if ( ( error = ft_var_load_gvar( face ) ) != 0 )
  1622          goto Exit;
  1623
  1624      if ( blend->normalizedcoords == NULL )
  1625      {
  1626        if ( FT_NEW_ARRAY( blend->normalizedcoords, mmvar->num_axis ) )
  1627          goto Exit;
  1628
  1629        manageCvt = mcvt_modify;
  1630
  1631        /* If we have not set the blend coordinates before this, then the  */
  1632        /* cvt table will still be what we read from the `cvt ' table and  */
  1633        /* we don't need to reload it.  We may need to change it though... */
  1634      }
  1635      else
  1636      {
  1637        manageCvt = mcvt_retain;
  1638
  1639        for ( i = 0; i < num_coords; i++ )
  1640        {
  1641          if ( blend->normalizedcoords[i] != coords[i] )
  1642          {
  1643            manageCvt = mcvt_load;
  1644            break;
  1645          }
  1646        }
  1647
  1648        for ( ; i < mmvar->num_axis; i++ )
  1649        {
  1650          if ( blend->normalizedcoords[i] != 0 )
  1651          {
  1652            manageCvt = mcvt_load;
  1653            break;
  1654          }
  1655        }
  1656
  1657        /* If we don't change the blend coords then we don't need to do  */
  1658        /* anything to the cvt table.  It will be correct.  Otherwise we */
  1659        /* no longer have the original cvt (it was modified when we set  */
  1660        /* the blend last time), so we must reload and then modify it.   */
  1661      }
  1662
  1663      blend->num_axis = mmvar->num_axis;
  1664      FT_MEM_COPY( blend->normalizedcoords,
  1665                   coords,
  1666                   num_coords * sizeof ( FT_Fixed ) );
  1667
  1668      face->doblend = TRUE;
  1669
  1670      if ( face->cvt != NULL )
  1671      {
  1672        switch ( manageCvt )
  1673        {
  1674        case mcvt_load:
  1675          /* The cvt table has been loaded already; every time we change the */
  1676          /* blend we may need to reload and remodify the cvt table.         */
  1677          FT_FREE( face->cvt );
  1678          face->cvt = NULL;
  1679
  1680          error = tt_face_load_cvt( face, face->root.stream );
  1681          break;
  1682
  1683        case mcvt_modify:
  1684          /* The original cvt table is in memory.  All we need to do is */
  1685          /* apply the `cvar' table (if any).                           */
  1686          error = tt_face_vary_cvt( face, face->root.stream );
  1687          break;
  1688
  1689        case mcvt_retain:
  1690          /* The cvt table is correct for this set of coordinates. */
  1691          break;
  1692        }
  1693      }
  1694
  1695      face->is_default_instance = is_default_instance;
  1696
  1697    Exit:
  1698      return error;
